// Anti-spam + normalização do intake Vortex
const sd = $getWorkflowStaticData('global');
const body = $json.body || {};
const headers = $json.headers || {};

// 1) Honeypot — drop silencioso
const honeypot = (body.website ?? '').toString().trim();
if (honeypot !== '') return [{ json: { spam: true, reason: 'honeypot' } }];

// 2) Validação de campos
const title = (body.title ?? '').toString().trim();
const description = (body.description ?? '').toString().trim();
const type = (body.type ?? '').toString().trim().toLowerCase();
if (title.length < 3 || title.length > 160) return [{ json: { spam: true, reason: 'title' } }];
if (description.length < 10 || description.length > 4000) return [{ json: { spam: true, reason: 'description' } }];
if (!['bug', 'feature'].includes(type)) return [{ json: { spam: true, reason: 'type' } }];

// 3) Rate-limit por instância (token bucket: burst 5, refill 5/hora)
const instance = (body.instance?.name ?? headers['x-forwarded-for'] ?? 'default').toString().slice(0, 100);
sd.buckets ??= {};
const now = Date.now();
const b = sd.buckets[instance] ??= { tokens: 5, ts: now };
b.tokens = Math.min(5, b.tokens + ((now - b.ts) / 3600000) * 5);
b.ts = now;
if (b.tokens < 1) return [{ json: { spam: true, reason: 'rate_limit' } }];
b.tokens -= 1;

// 4) Preparar payload do Plane (HTML saneado)
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const html = '<p>' + esc(description).replace(/\n{2,}/g, '</p><p>').replace(/\n/g, '<br>') + '</p>';
const instanceName = (body.instance?.name ?? 'desconhecida').toString().slice(0, 100);
const instanceUrl = (body.instance?.url ?? '').toString().slice(0, 200);
const userName = (body.user?.name ?? '').toString().slice(0, 120);
const userEmail = (body.user?.email ?? '').toString().slice(0, 200);
const reportedAt = (body.reported_at ?? new Date().toISOString()).toString();

const meta = [
  '<hr><p><strong>Instância:</strong> ' + esc(instanceName) + (instanceUrl ? ' (' + esc(instanceUrl) + ')' : '') + '</p>',
  '<p><strong>Reportado por:</strong> ' + esc(userName) + (userEmail ? ' &lt;' + esc(userEmail) + '&gt;' : '') + '</p>',
  '<p><strong>Data:</strong> ' + esc(reportedAt) + '</p>',
].join('\n');

return [{
  json: {
    spam: false,
    type,
    instanceName,
    planeIssue: {
      name: (type === 'bug' ? '[Bug] ' : '[Feature] ') + title,
      description_html: html + meta,
      priority: 'none',
      external_id: 'vortex-' + instance + '-' + now,
      external_source: 'vortex-intake',
    },
    notifyText: (type === 'bug' ? '🐞 Bug' : '✨ Feature') + ' de ' + instanceName + '\n' + title + '\n\n' + description.slice(0, 500) + '\n\nPor: ' + userName + (userEmail ? ' <' + userEmail + '>' : ''),
  },
}];
